import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Gauge } from '../types'
import { LABELS, advice, bar, crossed, level, percentLeft, refillText, toGauges } from './gauges'

const gauges = atom({ plugin: 'benzina', key: 'gauges' } as const, [])
const isHidden = atom({ plugin: 'benzina', key: 'isHidden' } as const, false)
const HIDDEN_KEY = 'isHidden'

async function store($: EngineInterface, found: Gauge[]): Promise<void> {
  const before = await read($, gauges)
  for (const gauge of found) {
    if (gauge.key === 'context') {
      continue
    }
    const previous = before.find(old => old.key === gauge.key)?.percentUsed
    const points = crossed(previous, gauge.percentUsed)
    const point = points[points.length - 1]
    if (point !== undefined) {
      const refill = refillText(gauge.resetsAt, await $.clock.now())
      $.ui.toast(
        `⛽ Hai usato il ${point}% del limite ${gauge.key === 'five_hour' ? 'delle 5 ore' : 'settimanale'}` +
          (refill === null ? '.' : `: si ricarica ${refill}.`),
      )
    }
  }
  await update($, gauges, () => found)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'benzina',
      description: 'Mostra o nasconde quanto ti resta del piano Claude e della chat',
    })
    const hidden = (await $.store.get(HIDDEN_KEY).catch(() => undefined)) === true
    await update($, isHidden, () => hidden)
    const usage = await $.session.usage().catch(() => null)
    if (usage !== null) {
      await update($, gauges, () => toGauges(usage.rateLimits, usage.context))
    }

    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    await store($, toGauges(e.rateLimits, e.context))

    return next(e)
  })

  on('command.run', { command: 'benzina' }, async $ => {
    const hidden = await update($, isHidden, value => !value)
    await $.store.set(HIDDEN_KEY, hidden).catch(() => undefined)

    return { text: hidden ? 'Indicatore nascosto. /benzina per rivederlo.' : 'Indicatore visibile sopra il prompt.' }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const below = await next(e)
    const found = await read($, gauges)
    const isQuiet =
      e.props.hasSurvey || e.props.view.agentId !== undefined || found.length === 0 || (await read($, isHidden))

    if (isQuiet) {
      return below
    }

    const { Box, Text } = $.ui.resolve(e)
    const now = await $.clock.now()
    const isNarrow = e.props.bodyColumns < 90
    const tip = advice(found, now)

    return (
      <Box flexDirection="column">
        <Box key="gauges" flexDirection="row" columnGap={2}>
          <Text>⛽</Text>
          {found.map(gauge => {
            const left = percentLeft(gauge)
            const refill = gauge.key === 'five_hour' && !isNarrow ? refillText(gauge.resetsAt, now) : null
            return (
              <Text key={`gauge-${gauge.key}`}>
                <Text dimColor>{LABELS[gauge.key]} </Text>
                {!isNarrow && <Text color={level(left)}>{bar(left)} </Text>}
                <Text color={level(left)}>{left}%</Text>
                {refill !== null && <Text dimColor> · ricarica {refill}</Text>}
              </Text>
            )
          })}
        </Box>
        {tip !== null && (
          <Text key="tip" color="warning">
            {tip}
          </Text>
        )}
        {below}
      </Box>
    )
  })
}

