import type { SessionContextUsage, SessionRateLimit } from 'claude-code'

import type { Gauge } from '../types'

export const LABELS: Record<Gauge['key'], string> = {
  five_hour: '5 ore',
  seven_day: 'Settimana',
  context: 'Chat',
}

// The points past which a toast warns once per window.
export const WARN_AT = [80, 95]

const DAYS = ['domenica', 'lunedì', 'martedì', 'mercoledì', 'giovedì', 'venerdì', 'sabato']

export function toGauges(rateLimits: SessionRateLimit[], context: SessionContextUsage): Gauge[] {
  const limits = rateLimits.flatMap((limit): Gauge[] =>
    limit.kind === 'five_hour' || limit.kind === 'seven_day'
      ? [{ key: limit.kind, percentUsed: limit.percentUsed, resetsAt: limit.resetsAt }]
      : [],
  )
  const order = (gauge: Gauge) => (gauge.key === 'five_hour' ? 0 : 1)
  const chat: Gauge[] = context.percent === undefined ? [] : [{ key: 'context', percentUsed: context.percent }]

  return [...limits.sort((a, b) => order(a) - order(b)), ...chat]
}

export function percentLeft(gauge: Gauge): number {
  return Math.max(0, Math.min(100, Math.round(100 - gauge.percentUsed)))
}

export function bar(left: number, width = 8): string {
  const full = Math.round((left / 100) * width)
  return '▰'.repeat(full) + '▱'.repeat(width - full)
}

export function level(left: number): 'success' | 'warning' | 'error' {
  return left > 40 ? 'success' : left > 15 ? 'warning' : 'error'
}

function clockTime(when: Date): string {
  return `${String(when.getHours()).padStart(2, '0')}:${String(when.getMinutes()).padStart(2, '0')}`
}

export function refillText(resetsAt: string | undefined, now: number): string | null {
  if (resetsAt === undefined) {
    return null
  }
  const when = new Date(resetsAt)
  if (Number.isNaN(when.getTime())) {
    return null
  }
  const isToday = new Date(now).toDateString() === when.toDateString()
  return isToday ? `alle ${clockTime(when)}` : `${DAYS[when.getDay()]} alle ${clockTime(when)}`
}

// One plain sentence for the tank that needs attention most, or nothing.
export function advice(gauges: Gauge[], now: number): string | null {
  for (const gauge of gauges) {
    if (gauge.key === 'context') {
      continue
    }
    const left = percentLeft(gauge)
    if (left <= 10) {
      const refill = refillText(gauge.resetsAt, now)
      const span = gauge.key === 'five_hour' ? 'Quasi a secco' : 'Settimana quasi finita'
      const until = refill === null ? '' : refill.startsWith('alle') ? ` fino ${refill}` : ` fino a ${refill}`
      return `${span}: tra poco Claude si ferma${until}.`
    }
  }
  const chat = gauges.find(gauge => gauge.key === 'context')
  if (chat !== undefined && percentLeft(chat) <= 25) {
    return 'La chat è lunga e Claude inizia a dimenticare: se passi a un\'altra cosa, scrivi /clear.'
  }
  return null
}

// The warning points a window crossed going from `before` to `after` percent used.
export function crossed(before: number | undefined, after: number): number[] {
  return WARN_AT.filter(point => after >= point && (before === undefined || before < point))
}

