export type Gauge = {
  /** Which tank: the 5-hour window, the weekly one, or the conversation. */
  key: 'five_hour' | 'seven_day' | 'context'
  percentUsed: number
  resetsAt?: string
}

declare module 'claude-code' {
  interface PluginState {
    benzina: {
      gauges: Gauge[]
      isHidden: boolean
    }
  }
}
